click.customFunction:
// opens the admin dashboard of the clicked customer
var customerId = entityId && entityId.id;
var customerName = entityName || '';

function open(dashboardId) {
    var url = '/dashboard/' + dashboardId;
    if (widgetContext.router && widgetContext.router.navigateByUrl) {
        widgetContext.router.navigateByUrl(url);
    } else {
        window.location.href = url;
    }
}

function fail(text) {
    if (widgetContext.showErrorToast) { widgetContext.showErrorToast(text, 'top'); }
    else { alert(text); }
}

// fallback: the dashboard called "Admin - <customer name>"
function byName() {
    var title = 'Admin - ' + customerName;
    widgetContext.http.get('/api/tenant/dashboards?pageSize=20&page=0&textSearch=' + encodeURIComponent(title)).subscribe(
        function (res) {
            var d = (res.data || []).filter(function (x) {
                return String(x.title).toLowerCase() === title.toLowerCase();
            })[0];
            if (d) { open(d.id.id); } else { fail('Nem található a(z) "' + title + '" dashboard.'); }
        },
        function () { fail('A dashboard keresése nem sikerült.'); }
    );
}

if (!customerId) {
    fail('A markerhez nem tartozik ügyfél.');
} else {
    // first choice: the dashboard id saved on the customer
    widgetContext.http.get('/api/plugins/telemetry/CUSTOMER/' + customerId +
                           '/values/attributes/SERVER_SCOPE?keys=adminDashboardId').subscribe(
        function (arr) {
            var a = (arr || []).filter(function (x) { return x.key === 'adminDashboardId'; })[0];
            if (a && a.value) { open(a.value); } else { byName(); }
        },
        function () { byName(); }
    );
}

